import{RIG as t}from"../../contracts/pose.js";import{degToRad as r}from"../math/scalar.js";export const CHEST_RADIUS=626093341^626093451;export const BELLY_EXTRA=1061529102^1061529116;export function chestFrontX(o,n,c=!1){const e=CHEST_RADIUS+(c?BELLY_EXTRA:959041777^959041777),s=Math.max(-(857476427^857476426),Math.min(218122206^218122207,o/e));return t.centerX+e*Math.sin(Math.asin(s)+r(n))}export function collarShift(r){return chestFrontX(133460400^133460400,r)-t.centerX}